(1,'lingkungan','level','Apa kepanjangan dari karhutla?','["Kebakaran hutan dan lahan", "Kerusakan hutan dan lahan", "Karbon hutan dan lahan", "Kebakaran hutan dan laut"]',0,'Karhutla adalah singkatan dari kebakaran hutan dan lahan.','pengertian',1,0),
(1,'penyebab','level','Menurut KLHK, tiga faktor penting penyebab karhutla adalah ...','["Manusia, rusaknya ekosistem gambut, dan cuaca", "Hanya petir, gempa, dan banjir", "Hanya kendaraan, pabrik, dan sampah plastik", "Hanya musim hujan yang panjang"]',0,'KLHK menyebut faktor manusia, rusaknya ekosistem gambut, dan cuaca.','penyebab',1,0),
(1,'penyebab','level','Salah satu pemicu karhutla dari perilaku manusia adalah ...','["Membakar untuk membuka lahan karena dianggap mudah dan murah", "Menanam pohon di tepi sungai", "Menyiram lahan gambut secara rutin", "Membuat sekat kanal"]',0,'Membakar untuk membuka lahan sering dipilih karena dianggap mudah dan murah, padahal berbahaya dan melanggar hukum.','penyebab',1,0),
(1,'kesehatan','level','Partikel halus dalam asap karhutla yang dapat masuk ke saluran pernapasan disebut ...','["PM2,5", "Pasir pantai", "Uap air", "Serbuk gergaji besar"]',0,'Asap karhutla mengandung partikel halus PM2,5.','pengertian',1,0),
(1,'kesehatan','level','Kelompok yang lebih rentan terhadap dampak kabut asap adalah ...','["Bayi, balita, ibu hamil, lansia, dan penderita asma atau penyakit paru", "Hanya atlet dewasa yang sehat", "Hanya orang yang tinggal jauh dari asap", "Tidak ada, semua orang sama sekali tidak berisiko"]',0,'Semua orang berisiko, tetapi kelompok tersebut lebih rentan.','kesehatan',1,0),
(1,'kesehatan','level','Saat kabut asap pekat, anjuran Kemenkes yang utama adalah ...','["Tetap berada di dalam rumah", "Berolahraga berat di luar rumah", "Membakar sampah agar asap tersamarkan", "Membuka semua jendela"]',0,'Kemenkes menganjurkan tetap di dalam rumah dan memakai masker bila harus keluar.','kesehatan',1,0),
(1,'kesehatan','level','Jika masker N95 tidak tersedia dan harus keluar rumah, anjuran yang disampaikan Menkes adalah ...','["Gunakan masker yang ada", "Tidak perlu memakai pelindung apa pun", "Tunggu sampai ada N95 lalu tetap keluar tanpa masker", "Gunakan kain basah menutup mata saja"]',0,'Menkes menyampaikan: pakai N95 bila ada, jika tidak ada gunakan masker yang ada.','kesehatan',1,0),
(1,'pencegahan','level','Lahan gambut yang terjaga kebasahannya membantu mencegah kebakaran. Hal ini dicapai antara lain lewat ...','["Pengelolaan tata air yang baik", "Pengeringan kanal sebanyak mungkin", "Pembakaran berkala", "Penebangan seluruh pohon"]',0,'Tata air yang baik menjaga gambut tetap basah sehingga lebih sulit terbakar.','pencegahan',1,0),
(1,'pencegahan','level','Kebakaran di lahan gambut sulit padam jika tidak ada ...','["Hujan", "Angin sepoi-sepoi", "Burung", "Cahaya bulan"]',0,'Karena sulit dipadamkan, mencegah kebakaran gambut jauh lebih efektif daripada memadamkannya.','pencegahan',1,0),
(1,'pencegahan','level','Pelibatan masyarakat untuk membuka lahan tanpa bakar disebut sebagai ...','["Kunci penting pencegahan karhutla", "Penyebab utama kabut asap", "Cara tercepat memicu api", "Hal yang tidak berpengaruh"]',0,'Membuka lahan tanpa bakar melibatkan masyarakat sebagai pelaku utama pencegahan.','pencegahan',1,0),
(1,'penyebab','pre','Mana yang BUKAN salah satu dari tiga faktor penting penyebab karhutla menurut KLHK?','["Perilaku manusia", "Rusaknya ekosistem gambut", "Cuaca", "Jumlah sekolah di desa"]',3,'Tiga faktornya adalah manusia, rusaknya ekosistem gambut, dan cuaca.','penyebab',1,0),
(1,'kesehatan','pre','Asap karhutla dapat memicu iritasi dan peradangan saluran pernapasan yang dikenal sebagai ...','["ISPA", "Patah tulang", "Rabun jauh", "Sakit gigi"]',0,'ISPA adalah infeksi saluran pernapasan akut.','kesehatan',1,0),
(1,'kesehatan','pre','Gejala yang tidak boleh diabaikan saat terpapar kabut asap adalah ...','["Batuk atau iritasi mata dan kulit", "Hanya rasa kantuk di malam hari", "Hanya rasa lapar", "Tidak ada gejala yang perlu diperhatikan"]',0,'Gejala seperti batuk atau iritasi perlu diperhatikan dan diperiksakan.','kesehatan',1,0),
(1,'pencegahan','pre','Langkah awal yang paling penting dalam pengendalian karhutla adalah ...','["Pencegahan", "Menunggu api membesar", "Menyalahkan cuaca", "Menutup sekolah"]',0,'Pencegahan adalah langkah awal yang paling penting.','pencegahan',1,0),
(1,'lingkungan','pre','Selain di permukaan, api di lahan gambut juga dapat ...','["Membakar bahan organik di bawah permukaan tanah", "Hanya terjadi di atas air", "Padam sendiri dalam satu menit", "Tidak pernah menimbulkan asap"]',0,'Di gambut, api dapat menjalar di bawah permukaan.','pengertian',1,0),
(1,'penyebab','post','Pemicu karhutla yang berasal dari manusia adalah ...','["Membakar lahan untuk membuka lahan", "Menanam bibit di lahan basah", "Menjaga tinggi muka air gambut", "Melapor saat melihat api"]',0,'Pembakaran untuk membuka lahan adalah pemicu dari manusia.','penyebab',1,0),
(1,'kesehatan','post','Cara mengurangi paparan asap yang dianjurkan Kemenkes adalah ...','["Tetap di dalam rumah, pakai masker bila keluar, dan minum air putih cukup", "Berlari di luar rumah saat asap pekat", "Tidak memakai masker sama sekali", "Menunggu sakit parah sebelum ke puskesmas"]',0,'Kemenkes menganjurkan tinggal di rumah, memakai masker saat keluar, minum air putih, dan menghindari aktivitas berat.','kesehatan',1,0),
(1,'kesehatan','post','Jika muncul keluhan pernapasan atau iritasi setelah terpapar asap, langkah yang tepat adalah ...','["Segera ke fasilitas kesehatan terdekat", "Menunggu berminggu-minggu", "Menambah aktivitas berat", "Mengabaikannya"]',0,'Kemenkes meminta warga segera ke fasilitas kesehatan bila ada keluhan.','kesehatan',1,0),
(1,'pencegahan','post','Mengapa mencegah kebakaran gambut lebih baik daripada memadamkannya?','["Karena kebakaran gambut sulit padam tanpa hujan", "Karena gambut tidak bisa terbakar", "Karena api gambut selalu kecil", "Karena pemadam tidak pernah dibutuhkan"]',0,'Kebakaran gambut sulit dipadamkan bila tidak turun hujan.','pencegahan',1,0),
(1,'lingkungan','post','Pengendalian karhutla mencakup ...','["Pencegahan, pemadaman, penanganan pascakebakaran, dukungan evakuasi, dan manajemen", "Hanya pemadaman", "Hanya penegakan denda", "Hanya imbauan di media sosial"]',0,'Pengendalian mencakup pencegahan, pemadaman, pascakebakaran, dukungan evakuasi dan penyelamatan, serta manajemen.','pencegahan',1,0);
